"""Voicing rules (docs/04 decision D7): the voicing is generated by rule, never free-form.

In the kernel the voicing is a set of numbers, not geometry. The add-on builds the geometry from
these numbers. Lengths are in millimetres in the Voicing record (the add-on works in mm); the
acoustic functions here work in metres and convert at the edge.

Inputs of the rule:
    target V0            capped air volume, all holes closed (cm^3)
    voice rating         soft 8.89 / medium 9.65 / loud 10.41 mm window length
    wall at window       default 4.0 mm; 3.0 mm is the other option (window_wall_options_mm)
    labium offset        default -0.2 mm (edge on the chamber side of the jet); coupons 0 and -0.35 mm
Derived:
    window area          solved so that eta_w * G_w reaches A4 at the target V0 (k_window = 0.80)
    window shape         a teardrop at every volume: broad end at the windway, narrow end (tip radius)
                         at the labium. Up to the volume where the broad end is a circle as wide as
                         the window is long, the outline is the hull of two circles. Above it the
                         teardrop is wider than long: the broad end is an ellipse (see "Window
                         geometry maths"). A rounded rectangle exists only as a forced option
                         (stub V-b compares window shapes at equal area).
    windway              exit height 1.20 mm; width = broad end of the window; length 30 mm; taper 2.5
                         (3.0 mm at the mouth end; 1.3 until 2026-11-18)
    labium               ramp 20 deg, edge 0.4 mm; keep-outs 10 mm inside, 45 deg flare outside
    build                how the add-on cuts the window and shapes the mouthpiece (owner decisions of
                         2026-11-18): the window cut, how far it opens sideways, the shelf above the windway
                         exit, the pitch of the windway about the labium edge, the blend of the pocket
                         behind the labium, and the style and the stance of the outer stub. See BUILD_FIELDS.

The voicing hash covers the numbers that define the voicing geometry (see `voicing_hash`). It does
not contain V0: V0 enters through the solved window area. A stub that carries the 80 cm^3 window
therefore has the same hash as the 80 cm^3 body, which is the point of Stage 1. The build fields
enter the hash only when they differ from the plain build (PLAIN_BUILD), so the hash of a plain
voicing is the one it had before the build was part of the record.
"""
from __future__ import annotations

import hashlib
import json
import math
from dataclasses import asdict, dataclass, field, replace

import checks
import config
import ocarina_kernel as ok

MM = 1e-3
CM3 = 1e-6

SHAPES = ("teardrop", "rounded_rectangle")


# --------------------------------------------------------------------------
# Window geometry maths (any one length unit; the callers use metres or millimetres)
# --------------------------------------------------------------------------

def window_area_for_conductance(G_w: float, t_w: float, k_window: float = ok.K_WINDOW) -> float:
    """Area A (m^2) with A / (t_w + k d_eq) = G_w. Closed form: with s = sqrt(A),
    s^2 - (2 k / sqrt(pi)) G s - G t = 0.
    """
    b = 2.0 * k_window / math.sqrt(math.pi) * G_w
    s = 0.5 * (b + math.sqrt(b * b + 4.0 * G_w * t_w))
    return s * s


# Teardrop family (owner decision 1, checkpoint C2b). The window is a teardrop at every volume.
#
#   x runs along the jet: x = 0 at the windway exit, x = length at the labium.
#   The outline is the convex hull of a BROAD END and a TIP CIRCLE.
#     tip circle   radius = tip radius; its far point is at x = length (the labium)
#     broad end    an ellipse with its back vertex at x = 0: half-width a = width / 2 across the jet,
#                  half-length b along the jet
#   width <= length   b = a. The broad end is a circle. This is the old two-circle teardrop, unchanged.
#   width >  length   b = (length / 2) * (length / width) ** wide_exponent. The broad end is an
#                     ellipse that is wider than long, and the tip stays a separate narrow end.
#   At width = length both rules give the circle of diameter `length`, so the family is continuous.
#   The area grows with the width over the whole family, and the outline is convex. Its smallest
#   radius of curvature is the tip radius, as long as the sides of the ellipse (radius b^2 / a) are
#   not sharper than the tip. That condition sets the largest width of the family.

WIDE_EXPONENT_DEFAULT = 1.0 / 3.0


def teardrop_circle_limit_area(length: float) -> float:
    """Area at width = length, where the broad end is a circle as wide as the window is long."""
    return math.pi * (length / 2.0) ** 2


def teardrop_min_area(length: float, tip_radius: float) -> float:
    """Smallest teardrop of the family: width = 2 * tip radius (a stadium)."""
    return ok.teardrop_area(length, 2.0 * tip_radius, tip_radius)


def teardrop_broad_half_length(length: float, width: float, wide_exponent: float = WIDE_EXPONENT_DEFAULT) -> float:
    """Half-length b of the broad end along the jet. For width <= length it is a circle (b = width / 2)."""
    if width <= length:
        return width / 2.0
    return (length / 2.0) * (length / width) ** wide_exponent


def teardrop_max_width(length: float, tip_radius: float, wide_exponent: float = WIDE_EXPONENT_DEFAULT) -> float:
    """Largest width of the family. There the sides of the broad ellipse are as sharp as the tip
    (b^2 / a = tip radius). A wider window would have sides sharper than the tip."""
    lo, hi = length, 100.0 * length
    for _ in range(70):
        mid = 0.5 * (lo + hi)
        b = teardrop_broad_half_length(length, mid, wide_exponent)
        if b * b / (mid / 2.0) > tip_radius:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def _support_crossing(length: float, a: float, b: float, r: float) -> float:
    """Normal angle (radians, 0..pi) where the hull changes from the tip circle to the broad end.

    Support functions about the windway exit point: tip h_T = (length - r) cos t + r, broad end
    h_E = b cos t + sqrt(b^2 cos^2 t + a^2 sin^2 t). Returns 0 when the tip circle is inside the broad end.
    """
    c = length - r

    def diff(t):
        return (c * math.cos(t) + r) - (b * math.cos(t) + math.sqrt((b * math.cos(t)) ** 2 + (a * math.sin(t)) ** 2))

    if diff(0.0) <= 1e-13 * length:
        return 0.0
    lo, hi = 0.0, math.pi
    for _ in range(70):
        mid = 0.5 * (lo + hi)
        if diff(mid) > 0.0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def _simpson(f, x0: float, x1: float, n: int = 400) -> float:
    if x1 <= x0:
        return 0.0
    h = (x1 - x0) / n
    s = f(x0) + f(x1)
    for i in range(1, n):
        s += f(x0 + i * h) * (4.0 if i % 2 else 2.0)
    return s * h / 3.0


def teardrop_area(length: float, width: float, tip_radius: float,
                  wide_exponent: float = WIDE_EXPONENT_DEFAULT) -> float:
    """Area of a teardrop of the family, for any width from 2 * tip radius up to the largest width.

    For width <= length this is the closed form of the two-circle hull (ok.teardrop_area), so the old
    teardrops keep their exact values. Above that the area is the integral of the support function,
    A = 1/2 * integral of (h^2 - h'^2) over the full turn.
    """
    if width <= length:
        if width >= length * (1.0 - 1e-12):
            return teardrop_circle_limit_area(length)
        return ok.teardrop_area(length, width, tip_radius)
    a, r = width / 2.0, tip_radius
    b = teardrop_broad_half_length(length, width, wide_exponent)
    c = length - r
    ts = _support_crossing(length, a, b, r)

    def tip(t):
        return (c * math.cos(t) + r) ** 2 - (c * math.sin(t)) ** 2

    def broad(t):
        q = math.sqrt((b * math.cos(t)) ** 2 + (a * math.sin(t)) ** 2)
        h = b * math.cos(t) + q
        dh = -b * math.sin(t) + (a * a - b * b) * math.sin(t) * math.cos(t) / q
        return h * h - dh * dh

    # Half a turn, doubled by symmetry, times the 1/2 of the formula.
    return _simpson(tip, 0.0, ts) + _simpson(broad, ts, math.pi)


def teardrop_width_for_area(length: float, area: float, tip_radius: float,
                            wide_exponent: float = WIDE_EXPONENT_DEFAULT) -> float:
    """Width of the broad end of a teardrop with the given length and area. Raises ValueError outside
    the family (area below the stadium, or above the widest teardrop). Bisection; the area grows with width."""
    if area < teardrop_min_area(length, tip_radius):
        raise ValueError("area is below the smallest teardrop; the window rule does not cover this volume")
    limit = teardrop_circle_limit_area(length)
    if area <= limit:
        if area >= limit * (1.0 - 1e-13):
            return length
        lo, hi = 2.0 * tip_radius, length
    else:
        lo, hi = length, teardrop_max_width(length, tip_radius, wide_exponent)
        if area > teardrop_area(length, hi, tip_radius, wide_exponent):
            raise ValueError("area is above the widest teardrop of the family (its sides would be sharper "
                             "than the tip); the window rule does not cover this volume")
    for _ in range(70):
        mid = 0.5 * (lo + hi)
        if teardrop_area(length, mid, tip_radius, wide_exponent) < area:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


def teardrop_outline(length: float, width: float, tip_radius: float,
                     wide_exponent: float = WIDE_EXPONENT_DEFAULT, step_deg: float = 1.5) -> list:
    """Outline of the teardrop as a closed polygon, counter-clockwise: a list of (x, y, normal angle).

    x runs along the jet (0 at the windway exit, `length` at the labium), y across. The normal angle
    (radians, -pi..pi) is the direction of the outward normal. |angle| < pi/2 is the labium side.
    The points lie on the true outline (tip arc, two straight flanks, broad end), one for every
    `step_deg` of normal angle, plus the tangent points. The polygon is inscribed, so its area is a
    little under the true area (about 0.01 % at 1.5 degrees).
    """
    a, r = width / 2.0, tip_radius
    b = teardrop_broad_half_length(length, width, wide_exponent)
    c = length - r
    ts = _support_crossing(length, a, b, r)
    pts = []
    if ts > 0.0:
        n_tip = max(2, int(math.ceil(2.0 * math.degrees(ts) / step_deg)))
        n_tip += n_tip % 2                             # even: the labium point (normal angle 0) is a vertex
        for i in range(n_tip + 1):                     # tip arc, normal angle from -ts to +ts
            t = -ts + 2.0 * ts * i / n_tip
            pts.append((c + r * math.cos(t), r * math.sin(t), t))
    n_broad = max(8, int(math.ceil(2.0 * math.degrees(math.pi - ts) / step_deg)))
    angles = [ts + 2.0 * (math.pi - ts) * i / n_broad for i in range(n_broad + 1)]
    if ts == 0.0:
        angles.pop()                                   # closed curve: do not repeat the first point
    # The widest points and the windway-exit point are always vertices, so the polygon has the exact
    # width and the exact length.
    for key in (0.5 * math.pi, math.pi, 1.5 * math.pi):
        if ts < key < 2.0 * math.pi - ts and all(abs(key - t) > 1e-9 for t in angles):
            angles.append(key)
    for t in sorted(angles):                           # broad end, normal angle from +ts over pi to -ts
        q = math.sqrt((b * math.cos(t)) ** 2 + (a * math.sin(t)) ** 2)
        pts.append((b + b * b * math.cos(t) / q, a * a * math.sin(t) / q, t if t <= math.pi else t - 2.0 * math.pi))
    return pts


def rounded_rectangle_area(length: float, width: float, corner_radius: float) -> float:
    return length * width - (4.0 - math.pi) * corner_radius ** 2


def rounded_rectangle_width_for_area(length: float, area: float, corner_radius: float) -> float:
    w = (area + (4.0 - math.pi) * corner_radius ** 2) / length
    if w < 2.0 * corner_radius:
        raise ValueError("rounded rectangle would be narrower than two corner radii")
    return w


def rounded_rectangle_outline(length: float, width: float, corner_radius: float, step_deg: float = 1.5) -> list:
    """Outline of the rounded rectangle (forced shape, stub V-b). Same conventions as teardrop_outline."""
    rc = corner_radius
    n = max(2, int(math.ceil(90.0 / step_deg)))
    pts = []
    corners = ((length - rc, width / 2.0 - rc, 0.0), (rc, width / 2.0 - rc, 0.5 * math.pi),
               (rc, -width / 2.0 + rc, math.pi), (length - rc, -width / 2.0 + rc, 1.5 * math.pi))
    for cx, cy, t0 in corners:
        for i in range(n + 1):
            t = t0 + 0.5 * math.pi * i / n
            pts.append((cx + rc * math.cos(t), cy + rc * math.sin(t), t if t <= math.pi else t - 2.0 * math.pi))
    return pts


def polygon_area(points) -> float:
    """Shoelace area of a closed polygon given as (x, y, ...) tuples. Positive for counter-clockwise."""
    s = 0.0
    n = len(points)
    for i in range(n):
        x0, y0 = points[i][0], points[i][1]
        x1, y1 = points[(i + 1) % n][0], points[(i + 1) % n][1]
        s += x0 * y1 - x1 * y0
    return 0.5 * s


# --------------------------------------------------------------------------
# The record
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class Voicing:
    """One generated voicing. Numbers only. Lengths in mm, angles in degrees."""
    rule_version: int
    shape: str                          # "teardrop" | "rounded_rectangle"
    rating: str                         # "soft" | "medium" | "loud"
    window_length_mm: float             # windway exit to labium edge (Heuer's window size)
    window_width_mm: float              # broad end (teardrop) or full width (rectangle)
    window_area_mm2: float
    tip_radius_mm: float                # teardrop narrow end; 0 for a rectangle
    corner_radius_mm: float             # rounded rectangle corners; 0 for a teardrop
    wall_at_window_mm: float
    windway_exit_height_mm: float
    windway_inlet_height_mm: float
    windway_width_mm: float
    windway_length_mm: float
    windway_taper_ratio: float
    labium_ramp_angle_deg: float
    labium_edge_thickness_mm: float
    labium_offset_mm: float
    keepout_inside_mm: float
    keepout_outside_flare_deg: float
    wh_ratio: float                     # window length / exit height
    version_hash: str                   # hash of the numbers above (see voicing_hash)
    # Information that is not part of the hash:
    designed_for_v0_cm3: float | None = None     # V0 the window area was solved for
    eta_w_assumed: float = 0.0                   # eta_w behind the solved area
    G_w_mm: float = 0.0                          # window conductance under k_window
    wh_band: tuple = (7.0, 10.0)
    # Teardrop wider than long (width > length). These two numbers enter the hash only for such a
    # window, so the hashes of the old teardrops do not change.
    broad_end_length_mm: float = 0.0             # length of the broad end along the jet (= width when it is a circle)
    wide_exponent: float = 0.0                   # exponent of the wide-teardrop rule; 0 when not used
    # The build (BUILD_FIELDS). The defaults are the plain build; these numbers enter the hash only when
    # they differ from it.
    window_cut: str = "fan"                      # "fan" | "cone" | "ellipse": how the window is opened to the outside
    cut_widen_mm: float = 0.0                    # cone, ellipse: the cut reaches this far beyond the window on each side at the outer face
    shelf_angle_deg: float = 0.0                 # cone, ellipse: the wall above the windway exit leans back by this angle from the normal
    windway_pitch_deg: float = 0.0               # the windway turned about the labium edge; negative = mouth end lowered toward the body
    pocket_blend_radius_mm: float = 0.0          # the pocket ceiling falls away behind the labium on this radius; 0 = a small step
    stub_style: str = "box"                      # "box" | "neck": the plastic around the windway
    stub_pitch_deg: float = 0.0                  # the outer stub turned about the labium edge; positive = it stands off the body

    @property
    def wh_ok(self) -> bool:
        return self.wh_band[0] <= self.wh_ratio <= self.wh_band[1]

    @property
    def window_area_m2(self) -> float:
        return self.window_area_mm2 * MM * MM

    @property
    def is_wide_teardrop(self) -> bool:
        return self.shape == "teardrop" and self.window_width_mm > self.window_length_mm

    def G_w(self, k_window: float = ok.K_WINDOW) -> float:
        """Window conductance in metres under k_window."""
        return ok.conductance(self.window_area_m2, self.wall_at_window_mm * MM, k_window)

    def outline_mm(self, step_deg: float = 1.5) -> list:
        """Window outline as a closed counter-clockwise polygon of (x, y, normal angle) in mm and radians.
        x = 0 at the windway exit, x = window length at the labium, y across the jet."""
        if self.shape == "teardrop":
            return teardrop_outline(self.window_length_mm, self.window_width_mm, self.tip_radius_mm,
                                    self.wide_exponent or WIDE_EXPONENT_DEFAULT, step_deg)
        return rounded_rectangle_outline(self.window_length_mm, self.window_width_mm, self.corner_radius_mm, step_deg)

    def to_dict(self) -> dict:
        d = asdict(self)
        d["wh_band"] = list(self.wh_band)
        return d

    def checks(self) -> list:
        return [checks.wh_ratio_check(self.window_length_mm * MM, self.windway_exit_height_mm * MM, self.wh_band)]

    @property
    def build(self) -> dict:
        return {k: getattr(self, k) for k in BUILD_FIELDS}

    @property
    def is_plain_build(self) -> bool:
        return _canon_build(self.build) == _canon_build(PLAIN_BUILD)


# Fields that define the geometry. The hash covers exactly these, plus the rule version.
HASH_FIELDS = (
    "rule_version", "shape", "window_length_mm", "window_width_mm", "window_area_mm2", "tip_radius_mm",
    "corner_radius_mm", "wall_at_window_mm", "windway_exit_height_mm", "windway_inlet_height_mm",
    "windway_width_mm", "windway_length_mm", "labium_ramp_angle_deg", "labium_edge_thickness_mm",
    "labium_offset_mm", "keepout_inside_mm", "keepout_outside_flare_deg",
)
# Extra fields that are hashed only for a teardrop wider than long.
HASH_FIELDS_WIDE = ("broad_end_length_mm", "wide_exponent")

# The build: how the add-on cuts the window and shapes the mouthpiece. PLAIN_BUILD is what every body had until
# 2026-11-18: the fan cut, a level windway, the box stub and no pocket blend. The build is hashed as a whole, and
# only when it differs from the plain build (owner decision 5 of 2026-11-18), so a plain voicing keeps its hash.
PLAIN_BUILD = {"window_cut": "fan", "cut_widen_mm": 0.0, "shelf_angle_deg": 0.0, "windway_pitch_deg": 0.0,
               "pocket_blend_radius_mm": 0.0, "stub_style": "box", "stub_pitch_deg": 0.0}
BUILD_FIELDS = tuple(PLAIN_BUILD)
WINDOW_CUTS = ("fan", "cone", "ellipse")
STUB_STYLES = ("box", "neck")

HASH_DECIMALS = 3        # 1 micrometre: stable against floating-point noise, finer than any printer


def _canon(x):
    """Canonical form for hashing: floats rounded to 1 um, negative zero removed."""
    if isinstance(x, float):
        r = round(x, HASH_DECIMALS)
        return 0.0 if r == 0.0 else r
    return x


def _canon_build(values: dict) -> dict:
    """The build fields of `values` in canonical form; a missing field is the plain one."""
    return {k: (str(values.get(k, plain)) if isinstance(plain, str) else _canon(float(values.get(k, plain))))
            for k, plain in PLAIN_BUILD.items()}


def voicing_hash(values: dict) -> str:
    """12 hex characters. `values` holds at least the HASH_FIELDS."""
    payload = {k: _canon(values[k]) for k in HASH_FIELDS}
    wide = (values.get("shape") == "teardrop"
            and round(float(values["window_width_mm"]), HASH_DECIMALS) > round(float(values["window_length_mm"]), HASH_DECIMALS))
    if wide:
        for k in HASH_FIELDS_WIDE:
            payload[k] = _canon(float(values[k]))
    build = _canon_build(values)
    if build != _canon_build(PLAIN_BUILD):
        payload.update(build)
    text = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def voicing_hash_of(v: Voicing) -> str:
    return voicing_hash(asdict(v))


def resolve_build(rules: dict, build=None) -> dict:
    """The build of a voicing as a checked dict of the BUILD_FIELDS.

    build   None: the values of [voicing_rules] (a rule table without them gives the plain build).
            "plain": PLAIN_BUILD.
            a dict: the values of [voicing_rules] with these fields replaced.
    """
    if isinstance(build, str):
        if build != "plain":
            raise ValueError(f"unknown build {build!r}; use \"plain\", a dict of build fields, or nothing")
        b = dict(PLAIN_BUILD)
    else:
        b = {k: rules.get(k, plain) for k, plain in PLAIN_BUILD.items()}
        unknown = sorted(set(build or {}) - set(BUILD_FIELDS))
        if unknown:
            raise ValueError(f"unknown build field(s) {', '.join(unknown)}; known: {', '.join(BUILD_FIELDS)}")
        b.update(build or {})
    return check_build(b)


def check_build(b: dict) -> dict:
    """Types and limits of a build. Returns a new dict."""
    b = {k: (str(b[k]) if isinstance(plain, str) else float(b[k])) for k, plain in PLAIN_BUILD.items()}
    if b["window_cut"] not in WINDOW_CUTS:
        raise ValueError(f"unknown window cut {b['window_cut']!r}; known: {', '.join(WINDOW_CUTS)}")
    if b["stub_style"] not in STUB_STYLES:
        raise ValueError(f"unknown stub style {b['stub_style']!r}; known: {', '.join(STUB_STYLES)}")
    if b["window_cut"] == "fan":
        if b["shelf_angle_deg"]:
            raise ValueError("shelf_angle_deg needs window_cut = cone or ellipse")
        b["cut_widen_mm"] = 0.0                                  # the fan cut has no sideways setting
    if b["cut_widen_mm"] < 0 or b["pocket_blend_radius_mm"] < 0 or not 0.0 <= b["shelf_angle_deg"] < 80.0:
        raise ValueError("cut_widen_mm and pocket_blend_radius_mm must not be negative; shelf_angle_deg is 0 to 80")
    if b["stub_style"] == "neck" and b["windway_pitch_deg"] > b["stub_pitch_deg"] + 1e-9:
        raise ValueError("the windway is raised above the roof line of the neck: stub_pitch_deg must be at least windway_pitch_deg")
    return b


def with_build(v: Voicing, **fields) -> Voicing:
    """The same voicing with some build fields replaced, and the hash of the result. For variant builds."""
    unknown = sorted(set(fields) - set(BUILD_FIELDS))
    if unknown:
        raise ValueError(f"unknown build field(s) {', '.join(unknown)}; known: {', '.join(BUILD_FIELDS)}")
    v2 = replace(v, **check_build(dict(v.build, **fields)))
    return replace(v2, version_hash=voicing_hash_of(v2))


# --------------------------------------------------------------------------
# The rule
# --------------------------------------------------------------------------

def make_voicing(v0_cm3: float | None = None, rating: str | None = None, wall_at_window_mm: float | None = None,
                 labium_offset_mm: float | None = None, *, eta_w: float | None = None, shape: str | None = None,
                 window_area_mm2: float | None = None, params: dict | None = None,
                 a4_hz: float | None = None, internal_temp_c: float | None = None, build=None) -> Voicing:
    """Generate the voicing for a target V0.

    v0_cm3             target capped air volume. Gives the window area through eta_w * G_w at A4.
    rating             "soft", "medium" (default) or "loud".
    wall_at_window_mm  default 4.0; must be one of [voicing_rules] window_wall_options_mm (3.0 or 4.0).
    labium_offset_mm   None = [voicing_rules] default_labium_offset_mm (-0.2); otherwise one of
                       labium_offset_options_mm (-0.35, -0.2, 0). Negative = edge below the jet centre.
    eta_w              window efficiency behind the solved area (default: the prior, 0.90).
    shape              None or "teardrop": a teardrop (the rule at every volume).
                       "rounded_rectangle" forces a rectangle of the same area (stub V-b only).
    window_area_mm2    use this area instead of solving it from V0 (fixed-voicing mode for Stage 3).
    build              None = the build of [voicing_rules]; "plain" = PLAIN_BUILD (fan cut, level windway,
                       box stub, no blend); a dict replaces single build fields. See resolve_build.
    """
    P = params if params is not None else config.load_params()
    R = P["voicing_rules"]
    D = P["design"]
    ratings = R["rating_window_mm"]
    rating = rating or R["default_rating"]
    if rating not in ratings:
        raise ValueError(f"unknown voice rating {rating!r}; use one of {sorted(ratings)}")
    wall = float(wall_at_window_mm if wall_at_window_mm is not None else R["default_wall_at_window_mm"])
    wall_options = R.get("window_wall_options_mm")
    if wall_options and not any(abs(wall - o) < 1e-9 for o in wall_options):
        raise ValueError(f"wall at the window {wall} mm is not one of {wall_options}")
    if labium_offset_mm is None:
        labium_offset_mm = float(R.get("default_labium_offset_mm", 0.0))
    if not any(abs(labium_offset_mm - o) < 1e-9 for o in R["labium_offset_options_mm"]):
        raise ValueError(f"labium offset {labium_offset_mm} mm is not one of {R['labium_offset_options_mm']}")
    if shape is not None and shape not in SHAPES:
        raise ValueError(f"unknown window shape {shape!r}")
    eta = float(eta_w if eta_w is not None else R["eta_w_prior"])

    L = float(ratings[rating]) * MM
    t_w = wall * MM
    tip = float(R["teardrop_tip_radius_mm"]) * MM
    corner = float(R["rect_corner_radius_mm"]) * MM
    wide_exp = float(R.get("teardrop_wide_exponent", WIDE_EXPONENT_DEFAULT))

    if window_area_mm2 is not None:
        area = float(window_area_mm2) * MM * MM
        v0_used = None
    else:
        if v0_cm3 is None:
            raise ValueError("give v0_cm3 or window_area_mm2")
        T = internal_temp_c if internal_temp_c is not None else D["design_air_temp_c"]
        c = ok.c_air(T)
        f0 = ok.midi_f(D["notes_midi"][0], a4_hz if a4_hz is not None else D["a4_hz"])
        G_eff = v0_cm3 * CM3 * (ok.TWO_PI * f0 / c) ** 2         # eta_w * G_w that puts A4 at f0
        area = window_area_for_conductance(G_eff / eta, t_w, ok.K_WINDOW)
        v0_used = float(v0_cm3)

    broad_len_mm = used_exp = 0.0
    if shape == "rounded_rectangle":
        width = rounded_rectangle_width_for_area(L, area, corner)
        shape_name, tip_mm, corner_mm = "rounded_rectangle", 0.0, corner / MM
    else:
        width = teardrop_width_for_area(L, area, tip, wide_exp)
        shape_name, tip_mm, corner_mm = "teardrop", tip / MM, 0.0
        broad_len_mm = 2.0 * teardrop_broad_half_length(L, width, wide_exp) / MM
        used_exp = wide_exp if width > L else 0.0

    h = float(R["windway_exit_height_mm"])
    taper = float(R["windway_taper_ratio"])
    values = dict(
        rule_version=int(R["rule_version"]), shape=shape_name, rating=rating,
        window_length_mm=L / MM, window_width_mm=width / MM, window_area_mm2=area / MM / MM,
        tip_radius_mm=tip_mm, corner_radius_mm=corner_mm, wall_at_window_mm=wall,
        windway_exit_height_mm=h, windway_inlet_height_mm=h * taper, windway_width_mm=width / MM,
        windway_length_mm=float(R["windway_length_mm"]), windway_taper_ratio=taper,
        labium_ramp_angle_deg=float(R["labium_ramp_angle_deg"]),
        labium_edge_thickness_mm=float(R["labium_edge_thickness_mm"]),
        labium_offset_mm=float(labium_offset_mm), keepout_inside_mm=float(R["keepout_inside_mm"]),
        keepout_outside_flare_deg=float(R["keepout_outside_flare_deg"]),
        wh_ratio=(L / MM) / h, broad_end_length_mm=broad_len_mm, wide_exponent=used_exp,
        **resolve_build(R, build),
    )
    G_w = ok.conductance(area, t_w, ok.K_WINDOW)
    return Voicing(version_hash=voicing_hash(values), designed_for_v0_cm3=v0_used, eta_w_assumed=eta,
                   G_w_mm=G_w / MM, wh_band=tuple(R["wh_ratio_band"]), **values)


def _v0_for_area(area_m2: float, rating: str, wall_at_window_mm, eta_w, params) -> float:
    P = params if params is not None else config.load_params()
    R, D = P["voicing_rules"], P["design"]
    t_w = (wall_at_window_mm if wall_at_window_mm is not None else R["default_wall_at_window_mm"]) * MM
    eta = eta_w if eta_w is not None else R["eta_w_prior"]
    G_w = ok.conductance(area_m2, t_w, ok.K_WINDOW)
    c = ok.c_air(D["design_air_temp_c"])
    f0 = ok.midi_f(D["notes_midi"][0], D["a4_hz"])
    return ok.volume_for(eta * G_w, f0, c) / CM3


def teardrop_circle_limit_v0_cm3(rating: str = "medium", wall_at_window_mm: float | None = None,
                                 eta_w: float | None = None, params: dict | None = None) -> float:
    """V0 at which the broad end of the teardrop is a circle as wide as the window is long
    (88.6 cm^3 for the medium window). Above it the teardrop is wider than long."""
    P = params if params is not None else config.load_params()
    L = P["voicing_rules"]["rating_window_mm"][rating] * MM
    return _v0_for_area(teardrop_circle_limit_area(L), rating, wall_at_window_mm, eta_w, P)


def teardrop_max_v0_cm3(rating: str = "medium", wall_at_window_mm: float | None = None,
                        eta_w: float | None = None, params: dict | None = None) -> float:
    """Largest V0 the teardrop family covers (the widest teardrop, see teardrop_max_width)."""
    P = params if params is not None else config.load_params()
    R = P["voicing_rules"]
    L = R["rating_window_mm"][rating] * MM
    tip = R["teardrop_tip_radius_mm"] * MM
    p = float(R.get("teardrop_wide_exponent", WIDE_EXPONENT_DEFAULT))
    w = teardrop_max_width(L, tip, p)
    return _v0_for_area(teardrop_area(L, w, tip, p), rating, wall_at_window_mm, eta_w, P)


def stub_pitch_hz(v: Voicing, stub_volume_cm3: float, eta_w: float | None = None, internal_temp_c: float = 27.0) -> float:
    """Predicted pitch of a Stage 1 voicing stub: a small chamber with this voicing and no holes.

    f = c / (2 pi) * sqrt(eta_w * G_w / V). Use it to check that the stub plays in a sensible range,
    and, after printing, to compare with the measured pitch (see fitter.eta_w_from_stub).
    """
    eta = eta_w if eta_w is not None else v.eta_w_assumed or 0.90
    return ok.freq(eta * v.G_w(), stub_volume_cm3 * CM3, ok.c_air(internal_temp_c))
